function bookView(book, baseUrl) {
  const statusLabel = book.status === 'reading' ? 'Currently reading' : 'Finished';
  const toggleLabel = book.status === 'reading' ? 'Mark finished' : 'Mark reading';
  return layout(book.title, `
    <p><a href="/">← Back to all books</a></p>
    <h1 style="font-size:1.8rem;margin:0.5rem 0">${esc(book.title)}</h1>
    <p class="author" style="margin:0 0 0.25rem">by ${esc(book.author || 'unknown')}</p>
