      <a class="btn" href="/books/${esc(book.id)}">Cancel</a>
    </form>
  `);
}

// ---------------------------------------------------------------------------
// Router
// ---------------------------------------------------------------------------

/** @param {import('node:http').IncomingMessage} req */
function baseUrlOf(req) {
  const host = req.headers.host || `localhost:${PORT}`;
  return `${req.headers['x-forwarded-proto'] || 'http'}://${host}`;
}

export async function handleRequest(req, books, { save }) {
  const url = new URL(req.url, 'http://localhost');
  const path = url.pathname;
  const method = req.method;

  // GET / — home
  if (path === '/' && method === 'GET') {
    return { view: () => homeView(books) };
  }

  // POST /books — create
  if (path === '/books' && method === 'POST') {
    const form = await readForm(req);
    if (!form.title) return { status: 400, view: () => layout('Error', '<p>A title is required.</p>') };
    const book = makeBook(form);
    books.push(book);
    await save();
    return { redirect: `/books/${book.id}` };
  }

  const m = path.match(/^\/books\/([^/]+)(?:\/(finish|edit|delete))?$/);
  if (m) {
    const id = decodeURIComponent(m[1]);
    const action = m[2];
    const book = books.find((b) => b.id === id);
    if (!book) return { status: 404, view: () => layout('Not found', '<p>No such book.</p><p><a href="/">Home</a></p>') };

    // GET /books/:id — detail
    if (!action && method === 'GET') {
      return { view: () => bookView(book, baseUrlOf(req)) };
    }

    // GET /books/:id/edit — edit form
    if (action === 'edit' && method === 'GET') {
      return { view: () => editView(book) };
    }

    // POST /books/:id — update
    if (!action && method === 'POST') {
      const form = await readForm(req);
      if (form.title) book.title = form.title.trim();
      book.author = (form.author || '').trim();
      book.notes = form.notes || '';
      await save();
      return { redirect: `/books/${book.id}` };
    }

    // POST /books/:id/finish — toggle status
    if (action === 'finish' && method === 'POST') {
      book.status = book.status === 'reading' ? 'finished' : 'reading';
      await save();
      return { redirect: '/books/' + book.id };
    }

    // POST /books/:id/delete — remove
    if (action === 'delete' && method === 'POST') {
      const idx = books.indexOf(book);
      if (idx >= 0) books.splice(idx, 1);
      await save();
      return { redirect: '/' };
    }
  }

  return { status: 404, view: () => layout('Not found', '<p>Page not found.</p><p><a href="/">Home</a></p>') };
}

// ---------------------------------------------------------------------------
// Server
// ---------------------------------------------------------------------------

export function createApp({ dataPath = DATA_PATH } = {}) {
  return createServer(async (req, res) => {
    try {
      const books = await loadBooks(dataPath);
      const save = () => saveBooks(books, dataPath);
      const result = await handleRequest(req, books, { save });

      if (result.redirect) return redirect(res, result.redirect);
      const status = result.status || 200;
      sendHtml(res, status, result.view());
    } catch (err) {
      console.error(err);
      sendHtml(res, 500, layout('Error', `<p>Something went wrong.</p><pre>${esc(err && err.stack ? err.stack : String(err))}</pre>`));
    }
  });
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (isMain) {
  if (!existsSync(DATA_PATH)) await saveBooks([]);
  const server = createApp();
  server.listen(PORT, () => {
    console.log(`Book tracker running at http://localhost:${PORT}`);
  });
}
"}

